import scipy.linalg.lapack

class Solver:
    def __init__(self, **kwargs):
        self.lwork = None

    def solve(self, problem, **kwargs):
        n = problem.shape[0]
        if self.lwork is None:
            self.lwork, _ = scipy.linalg.lapack.dgeev_lwork(n, compute_vl=0, compute_vr=0)

        wr, wi, info = scipy.linalg.lapack.dgeev(
            problem.T, 
            compute_vl=0, 
            compute_vr=0, 
            overwrite_a=1,
            lwork=self.lwork
        )[:3]

        idx = np.lexsort((-wi, -wr))
        vals = wr[idx] + 1j * wi[idx]
        return vals.tolist()
