from reference import Task
import numpy as np
from sklearn.neighbors import KernelDensity
from concurrent.futures import ThreadPoolExecutor

class Solver:
    def solve(self, problem):
        try:
            X = np.array(problem["data_points"])
            X_q = np.array(problem["query_points"])
            kernel = problem["kernel"]
            bandwidth = problem["bandwidth"]

            if X.ndim != 2 or X_q.ndim != 2:
                raise ValueError("Data points or query points are not 2D arrays.")
            if X.shape[0] == 0:
                raise ValueError("No data points provided.")
            if X_q.shape[0] == 0:
                return {"log_density": []}
            if X.shape[1] != X_q.shape[1]:
                raise ValueError("Data points and query points have different dimensions.")

            if not isinstance(bandwidth, (int, float)) or bandwidth <= 0:
                raise ValueError("Bandwidth must be positive.")
            bandwidth = float(bandwidth)

            kde = KernelDensity(kernel=kernel, bandwidth=bandwidth, algorithm='auto')
            kde.fit(X)

            num_workers = 4

            if X_q.shape[0] < 50:
                log_density = kde.score_samples(X_q)
            else:
                chunks = np.array_split(X_q, num_workers)
                def score_chunk(chunk):
                    if chunk.shape[0] == 0:
                        return np.array([])
                    return kde.score_samples(chunk)

                with ThreadPoolExecutor(max_workers=num_workers) as executor:
                    results = list(executor.map(score_chunk, chunks))
                log_density = np.concatenate(results)

            return {"log_density": log_density.tolist()}

        except Exception as e:
            return Task().solve(problem)

