import numpy as np
import scipy.linalg as la

class Solver:
    def __init__(self, **kwargs):
        pass

    def solve(self, problem: dict) -> dict:
        c = np.array(problem["c"])
        A = np.array(problem["A"])
        b = np.array(problem["b"])

        nu = np.zeros(b.shape)
        for _ in range(50):
            d = c + A.T @ nu
            x = 1.0 / d
            grad = b - A @ x
            H = A * (x**2) @ A.T

            try:
                delta = la.solve(H, -grad, assume_a='pos')
            except la.LinAlgError:
                delta = np.linalg.lstsq(H, -grad, rcond=None)[0]

            dec = -grad.dot(delta)
            if dec / 2 < 1e-12:
                break

            t = 1.0
            while np.any(c + A.T @ (nu + t * delta) <= 0):
                t *= 0.5

            f_old = b.dot(nu) - np.sum(np.log(d))
            grad_dot_delta = -dec

            for _ in range(20):
                nu_new = nu + t * delta
                d_new = c + A.T @ nu_new
                f_new = b.dot(nu_new) - np.sum(np.log(d_new))
                if f_new <= f_old + 0.01 * t * grad_dot_delta:
                    break
                t *= 0.5

            nu = nu + t * delta

        x_opt = 1.0 / (c + A.T @ nu)
        return {"solution": x_opt.tolist()}
